WITH OrderTotals AS (SELECT order_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(carrier))) AS carrier_values, ROUND((100 * SUM(CASE WHEN status = 'LOST' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_lost FROM shipments WHERE order_id IS NULL GROUP BY order_id) SELECT o.id, o.shipping_fee, O.carrier_values, O.pct_lost FROM orders o LEFT JOIN OrderTotals O ON o.id = O.order_id ORDER BY O.carrier_values DESC;
